    --balsa-material-surface: var(--balsa-color-surface);
    --balsa-material-surface-elevated: var(--balsa-color-surface-elevated);
    --balsa-material-muted: var(--balsa-color-muted);
    --balsa-material-input: var(--balsa-color-input);
    --balsa-material-input-border: var(--balsa-color-input-border);
    --balsa-material-selected: var(--balsa-color-selected);
    --balsa-material-border: var(--balsa-color-border);
    --balsa-material-border-strong: var(--balsa-color-border-strong);
    --balsa-material-code: var(--balsa-color-code);
    --balsa-material-playground-workspace: var(--balsa-color-muted);
    --balsa-material-playground-properties: var(--balsa-color-surface);
    --balsa-backdrop-blur: 0px;
    --balsa-overlay-blur: 0px;
  }
}

@media (prefers-reduced-motion: reduce) {
  :where([data-balsa]),
  :where([data-balsa])::before,
  :where([data-balsa])::after {
    scroll-behavior: auto;
    /* Accessibility safeguard: component and third-party animation declarations
       may otherwise outrank this user-preference override. */
    transition-duration: 1ms !important;
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
  }

  [data-theme] {
    --balsa-control-hover-transform: none;
    --balsa-control-active-transform: none;
  }
}

@media (forced-colors: active) {
  [data-theme] {
    --balsa-shadow-control: none;
    --balsa-shadow-surface: none;
    --balsa-shadow-panel: none;
    --balsa-shadow-playground: none;
    --balsa-backdrop-blur: 0px;
    --balsa-overlay-blur: 0px;
    --balsa-border-width: 2px;
  }
}

